import csv
import io

_DIGITS = '0123456789'


def _field(row, name):
    try:
        value = row[name]
    except KeyError:
        raise ValueError(f'missing {name} field')
    if value is None:
        raise ValueError(f'missing {name} field')
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f'{name} must not be empty')
    return value.strip()


def _parse_row(row):
    sku = _field(row, 'sku')
    name = _field(row, 'name')
    qty = _field(row, 'qty')
    if any(ch not in _DIGITS for ch in qty):
        raise ValueError('qty must be a nonnegative integer')
    return {'sku': sku, 'name': name, 'qty': int(qty)}


def import_text(text, store, dry_run=False):
    # Phase 1: validate every row and compute the diff from the starting
    # store state before committing anything (or, for a dry run, before
    # touching the store at all).
    planned = []
    reader = csv.DictReader(io.StringIO(text))
    for row in reader:
        item = _parse_row(row)
        planned.append((item, store.get(item['sku'])))

    # Phase 2: build the result and commit only when not a dry run.
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item, before in planned:
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
        if not dry_run:
            store.put(item)
    return result

